INSERT INTO upacara(id,kategori_yadnya_id,nama,deskripsi,jenis_penentuan) VALUES (42,1,'Banyupinaruh','Banyupinaruh (Redite Paing Wuku Sinta) adalah hari penyucian diri. Pada pagi hari umat melakukan penyucian diri (mandi suci / melukat) dan keramas dengan air kumkuman di sumber air (pantai, danau, campuhan, atau mata air). Sepulangnya, umat menghaturkan persembahan di Sanggah/Merajan dan pada lontar/buku suci sebelum disimpan kembali (nyineb Saraswati), lalu natab (ayaban) bersama keluarga.','hari_raya_tetap');
INSERT INTO upacara(id,kategori_yadnya_id,nama,deskripsi,jenis_penentuan) VALUES (43,1,'Soma Ribek','Soma Ribek (Soma Pon Wuku Sinta) adalah hari pemujaan ke hadapan Sang Hyang Tri Pramana / Sang Hyang Sri Amrta (Dewi Sri) yang berstana pada lumbung padi dan tempat penyimpanan beras/bahan pangan. Menurut Lontar Sundarigama, upakaranya tidak dibagi berdasarkan tingkatan yajna.','hari_raya_tetap');
INSERT INTO upacara(id,kategori_yadnya_id,nama,deskripsi,jenis_penentuan) VALUES (44,1,'Sabuh Mas','Sabuh Mas (Anggara Wage Wuku Sinta) adalah hari pemujaan ke hadapan Bhatara Mahadewa sebagai penguasa harta benda bernilai mulia seperti emas, perak, permata, keris, dan manik-manik (raja brana). Menurut Lontar Sundarigama, bantennya tidak dibedakan menurut tingkatan yajna.','hari_raya_tetap');
INSERT INTO upacara(id,kategori_yadnya_id,nama,deskripsi,jenis_penentuan) VALUES (45,1,'Sugihan Jawa','Sugihan Jawa (Wraspati Wage Wuku Sungsang, 6 hari sebelum Galungan; Jawa/Jaba = luar) bermakna penyucian Bhuana Agung, yaitu alam di luar diri manusia serta bangunan pelinggih di Merajan/Pura. Menurut Lontar Sundarigama, hari ini merupakan Pasucian Parama Siwa saat para Dewa dan Pitara turun untuk melaksanakan penyucian; pelinggih, bangunan, dan pekarangan rumah disucikan.','hari_raya_tetap');
INSERT INTO upacara(id,kategori_yadnya_id,nama,deskripsi,jenis_penentuan) VALUES (46,1,'Sugihan Bali','Sugihan Bali (Sukra Kliwon Wuku Sungsang, 5 hari sebelum Galungan; Wali = kembali ke dalam diri) bermakna penyucian Bhuana Alit, yaitu jiwa dan raga manusia, melalui pengendalian diri, penglukatan, dan pebersihan agar siap lahir dan batin menyongsong kemenangan Dharma pada Hari Raya Galungan.','hari_raya_tetap');
INSERT INTO upacara(id,kategori_yadnya_id,nama,deskripsi,jenis_penentuan) VALUES (47,1,'Penyajaan Galungan','Penyajaan Galungan (Soma Pon Wuku Dungulan, H-2 Galungan) adalah hari ketika umat mematangkan persiapan batin (nyajaang = bersungguh-sungguh) dan membuat aneka jajan (sesanganan) untuk kelengkapan banten Galungan, sekaligus mewaspadai godaan Sang Bhuta Dungulan.','hari_raya_tetap');
INSERT INTO upacara(id,kategori_yadnya_id,nama,deskripsi,jenis_penentuan) VALUES (48,1,'Penampahan Galungan','Penampahan Galungan (Anggara Wage Wuku Dungulan, H-1 Galungan) bermakna membunuh sifat keraksasaan (adharma) dalam diri, disimbolkan dengan menyembelih babi/ayam untuk diolah menjadi sarana upacara Galungan. Pada hari ini juga dinetralisir gangguan Sang Bhuta Amangkurat dan ditegakkan Penjor Galungan.','hari_raya_tetap');
INSERT INTO upacara(id,kategori_yadnya_id,nama,deskripsi,jenis_penentuan) VALUES (49,1,'Manis (Umanis) Galungan','Manis (Umanis) Galungan (Wraspati Umanis Wuku Dungulan, H+1 Galungan) adalah hari melaksanakan Dharma Shanti, yaitu saling mengunjungi keluarga/sanak saudara, serta ngelungsur (menurunkan) banten Galungan yang dihaturkan sehari sebelumnya.','hari_raya_tetap');
INSERT INTO upacara(id,kategori_yadnya_id,nama,deskripsi,jenis_penentuan) VALUES (50,1,'Ulihan Galungan & Pemacekan Agung','Ulihan Galungan dan Pemacekan Agung merujuk pada kembalinya para Dewata ke Kahyangan (ulih = pulang/kembali). Ulihan jatuh pada Redite Paing Wuku Kuningan dan Pemacekan Agung pada Soma Pon Wuku Kuningan. Pada sore hari (sandikala) Pemacekan Agung dihaturkan segehan untuk mengembalikan Sang Bhuta Galungan beserta pengiringnya ke tempat asalnya.','hari_raya_tetap');
INSERT INTO upacara(id,kategori_yadnya_id,nama,deskripsi,jenis_penentuan) VALUES (51,1,'Penampahan Kuningan','Penampahan Kuningan (Anggara Umanis Wuku Kuningan, H-1 Kuningan) adalah hari pembersihan diri secara niskala dan penyembelihan hewan kurban (babi/ayam) untuk diolah menjadi sarana upacara, sehari sebelum para Dewata dan Pitara kembali ke Kahyangan.','hari_raya_tetap');
INSERT INTO upacara(id,kategori_yadnya_id,nama,deskripsi,jenis_penentuan) VALUES (52,1,'Buda Kliwon Pegatwakan','Buda Kliwon Pegatwakan (Buda Kliwon Wuku Pahang, 35 hari setelah Galungan) adalah hari nyabut (mencabut) penjor Galungan, sebagai wujud syukur kepada Ida Sang Hyang Widhi Wasa atas kerahayuan selama rangkaian Galungan dan Kuningan hingga paripurna. Banten dihaturkan di dekat penjor sebelum dicabut, menandakan berakhirnya rangkaian hari raya; penjor lalu dibersihkan/dihanyutkan/dibakar sesuai dresta setempat.','hari_raya_tetap');
INSERT INTO upacara(id,kategori_yadnya_id,nama,deskripsi,jenis_penentuan) VALUES (53,1,'Odalan Bhatara Hyang Guru','Odalan Bhatara Hyang Guru jatuh sehari setelah Tumpek Landep, yaitu Redite Umanis Wuku Ukir. Ini adalah piodalan untuk Bhatara Hyang Guru yang berstana di Sanggah Kemulan. Tingkatan nista untuk piodalan rutin atau kecil di merajan keluarga, madya untuk piodalan pamerajan keluarga dalam batas kewenangan Pinandita/Pemangku, dan utama untuk piodalan besar di merajan agung atau pamerajan dadia yang dipimpin Sulinggih/Pandita.','hari_raya_tetap');
INSERT INTO upacara(id,kategori_yadnya_id,nama,deskripsi,jenis_penentuan) VALUES (55,1,'Melaspas Motor/Mobil','Melaspas Motor/Mobil adalah upacara pemelaspasan atau pasupati kendaraan, dengan sarana antara lain Banten Pejati sebagai pemakluman/memohon restu, Banten Ayaban Tumpeng 5, Sayut Pangambean/Sayut Pasupati, Prayascita untuk pembersihan dan penyucian, serta Banten Durmanggala.','dewasa');
