INSERT INTO kutipan(id,sumber_id,teks,halaman) VALUES (2054,9,'Canang Sari / Canang Genten: Dilengkapi dengan dupa sebagai wujud bakti di sumber air.','Dewa p8+');
INSERT INTO kutipan(id,sumber_id,teks,halaman) VALUES (2055,9,'Canang Burat Wangi & Lenga Wangi: Digunakan sebagaimana peruntukan hari suci Saraswati.','Dewa p8+');
INSERT INTO kutipan(id,sumber_id,teks,halaman) VALUES (2056,9,'Canang Pesucian (Pembersihan): Berisi 7 jenis alat pembersihan, yaitu sisig (pembersih gigi), ambuh (bahan keramas dari daun kembang sepatu yang disisir halus atau kelapa/santan), kekosok putih (lulur tepung beras), tepung tawar (campuran daun dapdap, beras, kunyit), wija/sesarik, tetebus (benang putih), dan minyak wangi/kelapa.','Dewa p8+');
INSERT INTO kutipan(id,sumber_id,teks,halaman) VALUES (2057,9,'Segehan Kepel / Segehan Cacahan: Dihaturkan di bawah (sor) di tepi sumber air untuk menetralisir unsur negatif.','Dewa p8+');
INSERT INTO kutipan(id,sumber_id,teks,halaman) VALUES (2058,9,'Banten Pejati (Ke Surya / Penguasa Sumber Air): Pras, Daksina, Sodan/Rayunan/Ajuman, dan Tipat Kelanan.','Dewa p8+');
INSERT INTO kutipan(id,sumber_id,teks,halaman) VALUES (2059,9,'Banten Pebersihan & Penglukatan: Banten Byakala, Prayascita, dan Durmanggala (digunakan apabila melaksanakan prosesi melukat bersama Pinandita/Pemangku).','Dewa p8+');
INSERT INTO kutipan(id,sumber_id,teks,halaman) VALUES (2060,9,'Canang Pesucian & Toya Kumkuman: Air bersih yang dicampur kembang harum dan air cendana untuk keramas dan membasuh kepala.','Dewa p8+');
INSERT INTO kutipan(id,sumber_id,teks,halaman) VALUES (2061,9,'Banten Sor: Segehan Manca Warna atau Segehan Cacahan.','Dewa p8+');
INSERT INTO kutipan(id,sumber_id,teks,halaman) VALUES (2062,9,'Sodan / Rayunan / Ajuman (Labahan): Beralas taledan/tamas berisi dua buah penek, rerasmen, buah-buahan, kue-kue, dan sampian kepet-kepetan/pelaus.','Dewa p8+');
INSERT INTO kutipan(id,sumber_id,teks,halaman) VALUES (2063,9,'Canang Sari, Canang Burat Wangi, & Canang Tadah Sukla: Sebagai pelengkap persembahan pada hari suci Saraswati dan rentetannya.','Dewa p8+');
INSERT INTO kutipan(id,sumber_id,teks,halaman) VALUES (2064,9,'Banten Sor: Segehan.','Dewa p8+');
INSERT INTO kutipan(id,sumber_id,teks,halaman) VALUES (2065,9,'Di Padmasana / Kemulan: Pras, Daksina, Sodan/Rayunan/Ajuman, dan Tipat Kelanan.','Dewa p8+');
INSERT INTO kutipan(id,sumber_id,teks,halaman) VALUES (2066,9,'Nasi Pradnyan / Nasi Kuning: Nasi atau penek kuning lengkap dengan lauk-pauk yang melambangkan kecerdasan dan kemuliaan (pradnyan).','Dewa p8+');
INSERT INTO kutipan(id,sumber_id,teks,halaman) VALUES (2067,9,'Dapetan, Pengambean, Pengulapan, dan Pras (atau Tumpeng Pitu): Sebagaimana susunan tataban hari suci di lapan.','Dewa p8+');
INSERT INTO kutipan(id,sumber_id,teks,halaman) VALUES (2068,9,'Sesayut Saraswati / Sesayut Pageh Tuwuh & Prayascita: Untuk memohon keteguhan ilmu pengetahuan dan kesucian lahir batin.','Dewa p8+');
INSERT INTO kutipan(id,sumber_id,teks,halaman) VALUES (2069,9,'Toya Kumkuman (Air Kembang Harum): Digunakan untuk memerciki ubun-ubun serta diminum (tirtha) seusai sembahyang.','Dewa p8+');
INSERT INTO kutipan(id,sumber_id,teks,halaman) VALUES (2070,9,'Nasi Sok-sokan / Sodan Putih Kuning: Nasi yang ditempatkan di dalam wakul/tamas lengkap dengan lauk-pauk (rerasmen).','Dewa p8+');
INSERT INTO kutipan(id,sumber_id,teks,halaman) VALUES (2071,9,'Banten khusus Lontar Sundarigama: Tipat Sari, Tipat Bagia, Nasi Sasah, rerasmen, raka-raka (buah-buahan dan jajan), serta Canang Lenga Wangi dan Burat Wangi.','Dewa p8+');
INSERT INTO kutipan(id,sumber_id,teks,halaman) VALUES (2072,9,'Dapetan & Canang Sari: Beralaskan taledan berisi sebuah tumpeng, sesanganan, tebu, buah-buahan, rerasmen, sampian dapetan, dan Canang Sari.','Dewa p8+');
INSERT INTO kutipan(id,sumber_id,teks,halaman) VALUES (2073,9,'Banten Pejati / Sodan: Pras, Daksina, Sodan/Rayunan/Ajuman, dan Tipat Kelanan (atau minimal Sodan/Rayunan/Ajuman dan Canang Sari).','Dewa p8+');
INSERT INTO kutipan(id,sumber_id,teks,halaman) VALUES (2074,9,'Segehan (Segehan Kepel atau Segehan Cacahan).','Dewa p8+');
INSERT INTO kutipan(id,sumber_id,teks,halaman) VALUES (2075,9,'Banten Pokok (Lontar Sundarigama): Suci, Daksina, Pras, Penyeneng, Sesayut Amerta Sari, Canang Lenga Wangi Burat Wangi, serta Rantasan (kain putih/kuning).','Dewa p8+');
INSERT INTO kutipan(id,sumber_id,teks,halaman) VALUES (2076,9,'Sodan / Rayunan Kuning: Menggunakan nasi kuning atau tumpeng kuning lengkap dengan lauk-pauk (seperti itik atau telur) dan raka-raka yang melambangkan warna Bhatara Mahadewa (kuning).','Dewa p8+');
INSERT INTO kutipan(id,sumber_id,teks,halaman) VALUES (2077,9,'Pras, Daksina, Sodan/Rayunan/Ajuman, dan Tipat Kelanan (Pejati).','Dewa p8+');
INSERT INTO kutipan(id,sumber_id,teks,halaman) VALUES (2078,9,'Segehan (Segehan Kuning atau Segehan Cacahan).','Dewa p8+');
INSERT INTO kutipan(id,sumber_id,teks,halaman) VALUES (2079,9,'Banten Pejati (Ke Surya / Kemulan): Pras, Daksina, Sodan/Rayunan/Ajuman, dan Tipat Kelanan.','Dewa p8+');
INSERT INTO kutipan(id,sumber_id,teks,halaman) VALUES (2080,9,'Banten Pebersihan / Reresik Pelinggih: Canang Pesucian (Pembersihan) lengkap dengan 7 unsur penyucian (sisig, ambuh, kekosok putih, tepung tawar, wija/sesarik, tetebus, dan minyak wangi), disertai Canang Burat Wangi, Lenga Wangi, dan Canang Sari.','Dewa p8+');
INSERT INTO kutipan(id,sumber_id,teks,halaman) VALUES (2081,9,'Banten Ayaban / Lapan (Lontar Sundarigama): Sodan/Rayunan/Ajuman, Dapetan, serta banten Eedan / Raka-raka (berisi aneka buah-buahan, jajan, dan pisang).','Dewa p8+');
INSERT INTO kutipan(id,sumber_id,teks,halaman) VALUES (2082,9,'Banten Prayascita dan Byakala: Digunakan untuk menyucikan pelinggih, bangunan, dan pekarangan rumah agar bersih menyambut turunnya para Dewa dan Leluhur.','Dewa p8+');
INSERT INTO kutipan(id,sumber_id,teks,halaman) VALUES (2083,9,'Segehan Agung atau Segehan Manca Warna / Segehan Cacahan yang dilengkapi tetabuhan (tuak, arak, berem, dan air) di halaman merajan dan di depan pintu keluar pekarangan (lebuh).','Dewa p8+');
INSERT INTO kutipan(id,sumber_id,teks,halaman) VALUES (2084,9,'Padmasana / Kemulan: Pras, Daksina, Sodan/Rayunan/Ajuman, Tipat Kelanan, dan Canang Sari.','Dewa p8+');
INSERT INTO kutipan(id,sumber_id,teks,halaman) VALUES (2085,9,'Banten Pebersihan & Penglukatan (Lontar Sundarigama): Banten Prayascita, Banten Byakala, dan Banten Penglukatan (dilengkapi dengan Tirtha Penglukatan, Tirtha Pebersihan, atau Toya Bungkak Nyuh Gading dan Canang Pesucian).','Dewa p8+');
INSERT INTO kutipan(id,sumber_id,teks,halaman) VALUES (2086,9,'Banten Tataban / Ayaban Manusia: Dapetan (atau Pras, Pengulap, Pengambean, Dapetan) dan Sesayut (seperti Sesayut Pageh Tuwuh atau Sesayut Sudamala untuk keteguhan jiwa dan peleburan mala/kotoran diri).','Dewa p8+');
INSERT INTO kutipan(id,sumber_id,teks,halaman) VALUES (2087,9,'Canang Sari / Canang Genten: Dihaturkan di pelinggih serta di dapur sebelum mulai membuat jajan (sesanganan) agar diberikan kelancaran dan kesucian.','Dewa p8+');
INSERT INTO kutipan(id,sumber_id,teks,halaman) VALUES (2088,9,'Sodan / Rayunan / Ajuman (Opsional sesuai dresta): Beralas taledan/tamas berisi dua buah penek, rerasmen, buah-buahan, kue/jajan yang baru selesai dibuat, dan sampian kepet-kepetan/pelaus.','Dewa p8+');
INSERT INTO kutipan(id,sumber_id,teks,halaman) VALUES (2089,9,'Segehan Kepel / Segehan Cacahan: Dihaturkan di halaman merajan, halaman rumah, dan di depan pintu keluar pekarangan (lebuh) lengkap dengan tetabuhan untuk menetralisir pengaruh negatif Sang Bhuta Dungulan.','Dewa p8+');
INSERT INTO kutipan(id,sumber_id,teks,halaman) VALUES (2090,9,'Banten Jotan / Sagi-sagi: Begitu masakan olahan daging (seperti lawar, urutan, sate, tum, komoh) selesai dimasak dan sebelum disantap oleh keluarga, wajib dihaturkan terlebih dahulu berupa nasi hangat di atas daun pisang/taledan kecil lengkap dengan semua jenis olahan daging tersebut, garam, dan Canang Sari.','Dewa p8+');
INSERT INTO kutipan(id,sumber_id,teks,halaman) VALUES (2091,9,'Dapetan / Tumpeng Kecil & Tipat Kelanan: Beralas taledan/ceper berisi dua buah tumpeng kecil atau penek, rerasmen, raka-raka, sampian, dan Canang Sari/Canang Burat Wangi saat penjor baru selesai ditegakkan.','Dewa p8+');
INSERT INTO kutipan(id,sumber_id,teks,halaman) VALUES (2092,9,'Segehan Agung atau Segehan Manca Warna / Segehan Sasah (Nasi Wong-wongan): Dilengkapi dengan olahan darah dan daging mentah (urab barak, urab putih, gegecok), sate, bawang, jahe, garam, serta tetabuhan (tuak, arak, berem, dan air) yang dihaturkan di halaman rumah dan di depan pintu masuk (lebuh) pada sore hari (sandikala) untuk Sang Bhuta Amangkurat dan Sang Kala Tiga.','Dewa p8+');
INSERT INTO kutipan(id,sumber_id,teks,halaman) VALUES (2093,9,'Canang Sari, Canang Genten, & Canang Burat Wangi: Dihaturkan di seluruh pelinggih dan pada Penjor Galungan sebelum memohon (ngelungsur) ayaban banten Galungan.','Dewa p8+');
INSERT INTO kutipan(id,sumber_id,teks,halaman) VALUES (2094,9,'Sodan / Rayunan / Ajuman (Labahan Anyar): Nasi penek yang baru dimasak lengkap dengan rerasmen, buah-buahan, jajan, dan sampian kepet-kepetan/pelaus sebagai persembahan di pagi hari.','Dewa p8+');
INSERT INTO kutipan(id,sumber_id,teks,halaman) VALUES (2095,9,'Sesayut Pageh Tuwuh / Sesayut Jayeng Ratu & Prayascita: Untuk memohon keteguhan hidup serta kesucian pikiran setelah merayakan kemenangan Dharma.','Dewa p8+');
INSERT INTO kutipan(id,sumber_id,teks,halaman) VALUES (2096,9,'Tirtha Kumkuman / Toya Anyar: Digunakan untuk menyucikan diri sebelum ngelungsur banten.','Dewa p8+');
INSERT INTO kutipan(id,sumber_id,teks,halaman) VALUES (2097,9,'Segehan (Segehan Kepel atau Segehan Cacahan) di halaman merajan dan di bawah Penjor Galungan.','Dewa p8+');
INSERT INTO kutipan(id,sumber_id,teks,halaman) VALUES (2098,9,'Di Sanggah / Merajan (Padmasana & Kemulan): Pras, Daksina, Sodan/Rayunan/Ajuman, Tipat Kelanan, dan Canang Sari.','Dewa p8+');
INSERT INTO kutipan(id,sumber_id,teks,halaman) VALUES (2099,9,'Di Lapan / Persembahan: Dapetan (atau Tumpeng Pitu: Pras, Pengulapan, Pengambean, Dapetan) serta Canang Meraka / Gebogan sebagai ungkapan syukur mengiringi kembalinya para Dewa.','Dewa p8+');
INSERT INTO kutipan(id,sumber_id,teks,halaman) VALUES (2100,9,'Di Sanggah / Merajan: Sodan/Rayunan/Ajuman dan Canang Sari.','Dewa p8+');
INSERT INTO kutipan(id,sumber_id,teks,halaman) VALUES (2101,9,'Di Halaman Rumah & Di Depan Pintu Gerbang (Lebuh) pada Sore Hari (Sandikala): Segehan Agung (beralas nyiru/tempeh berisi 11 tangkih nasi putih berlauk bawang, jahe, garam dengan sebuah daksina di tengahnya), dilengkapi dengan Nasi Sok-sokan / Takilan, Sate Calon / Sate Asem, serta tetabuhan tuak, arak, berem, dan air untuk mengembalikan Sang Bhuta Galungan beserta para pengiringnya ke tempat asalnya masing-masing.','Dewa p8+');
INSERT INTO kutipan(id,sumber_id,teks,halaman) VALUES (2102,9,'Banten Jotan / Sagi-sagi: Begitu masakan olahan daging selesai dimasak, wajib dihaturkan terlebih dahulu berupa nasi hangat di atas daun pisang/taledan kecil lengkap dengan olahan daging, garam, dan Canang Sari.','Dewa p8+');
INSERT INTO kutipan(id,sumber_id,teks,halaman) VALUES (2103,9,'Segehan Agung atau Segehan Manca Warna: Dilengkapi dengan olahan daging mentah, bumbu, serta tetabuhan (tuak, arak, berem, dan air) di halaman rumah dan pintu masuk (lebuh) pada sore hari (sandikala) untuk menetralisir unsur negatif.','Dewa p8+');
INSERT INTO kutipan(id,sumber_id,teks,halaman) VALUES (2104,9,'Banten Pejati / Sodan: Pras, Daksina, Sodan/Rayunan/Ajuman, dan Tipat Kelanan (atau minimal Sodan/Rayunan/Ajuman dan Canang Sari) sebagai wujud rasa syukur kepada Ida Sang Hyang Widhi Wasa atas kerahayuan selama rangkaian Galungan dan Kuningan hingga paripurna.','Dewa p8+');
INSERT INTO kutipan(id,sumber_id,teks,halaman) VALUES (2105,9,'Canang Burat Wangi & Lenga Wangi: Sebagai pelengkap persembahan suci.','Dewa p8+');
INSERT INTO kutipan(id,sumber_id,teks,halaman) VALUES (2106,9,'Canang Sari & Daksina / Sodan Sederhana: Dihaturkan di dekat penjor sebelum penjor tersebut dicabut/dilepas, menandakan berakhirnya rangkaian hari raya dan penjor dibersihkan/dihanyutkan/dibakar abunya sesuai dresta setempat.','Dewa p8+');
INSERT INTO kutipan(id,sumber_id,teks,halaman) VALUES (2107,9,'Segehan Kepel / Segehan Cacahan: Dihaturkan di halaman merajan, pekarangan rumah, dan di depan pintu masuk (lebuh) lengkap dengan tetabuhan untuk mengembalikan keseimbangan alam (Bhuta Yajna)','Dewa p8+');
INSERT INTO kutipan(id,sumber_id,teks,halaman) VALUES (2108,9,'Banten Pejati: Pras, Daksina, Ajuman, Tipat Kelanan, dan Canang Sari.','Dewa p8+');
INSERT INTO kutipan(id,sumber_id,teks,halaman) VALUES (2109,9,'Sodan / Rayunan / Ajuman: Sebagai banten labahan harian.','Dewa p8+');
INSERT INTO kutipan(id,sumber_id,teks,halaman) VALUES (2110,9,'Segehan Kepel atau Segehan Cacahan lengkap dengan tetabuhan air atau arak/berem secukupnya.','Dewa p8+');
INSERT INTO kutipan(id,sumber_id,teks,halaman) VALUES (2111,9,'Banten Pejati & Banten Suci: Pras, Daksina, Ajuman, Tipat Kelanan, serta Banten Suci (Suci Sari / Alit) yang menggunakan 3 tamas (tamas jajan, tamas nasi/tumpeng guru, dan tamas lelampadan).','Dewa p8+');
INSERT INTO kutipan(id,sumber_id,teks,halaman) VALUES (2112,9,'Banten Ayaban / Tataban: Tumpeng Pitu (7) atau tumpeng belasan, dilengkapi dengan Pulagembal dan Sekar Setaman.','Dewa p8+');
INSERT INTO kutipan(id,sumber_id,teks,halaman) VALUES (2113,9,'Banten Guru Piduka: Khusus dihaturkan untuk memohon pengampunan atas segala kesalahan dan dosa yang tidak disadari, di mana di dalamnya menggunakan simbol telur itik (taluh pinaka Guru).','Dewa p8+');
INSERT INTO kutipan(id,sumber_id,teks,halaman) VALUES (2114,9,'Segehan Agung atau Segehan Manca Warna untuk menetralisir unsur negatif di sekitar area merajan.','Dewa p8+');
INSERT INTO kutipan(id,sumber_id,teks,halaman) VALUES (2115,9,'Banten Suci Laksana / Suci Gede (menggunakan 6 hingga 10 tamas lengkap dengan sancak dan wedia).','Dewa p8+');
INSERT INTO kutipan(id,sumber_id,teks,halaman) VALUES (2116,9,'Banten Catur (jika menggunakan tingkatan Catur Rebah atau Catur Muka pada sanggar surya/pesaksi).','Dewa p8+');
INSERT INTO kutipan(id,sumber_id,teks,halaman) VALUES (2117,9,'Banten Ayaban Utama: Pulagembal Bebangkit, Jerimpen, Gebogan, serta dilengkapi dengan Rantasan.','Dewa p8+');
INSERT INTO kutipan(id,sumber_id,teks,halaman) VALUES (2118,9,'Dilengkapi dengan upacara pecaruan mulai dari Caru Panca Sata, Caru Panca Kelud, hingga Caru Balik Sumpah tergantung pada tingkatan upacaranya.','Dewa p8+');
INSERT INTO kutipan(id,sumber_id,teks,halaman) VALUES (2124,9,'Banten Pejati (sebagai sarana pemakluman/memohon restu).','Dewa p8+');
INSERT INTO kutipan(id,sumber_id,teks,halaman) VALUES (2125,9,'Banten Ayaban Tumpeng 5.','Dewa p8+');
INSERT INTO kutipan(id,sumber_id,teks,halaman) VALUES (2126,9,'Sayut Pangambean / Sayut Pasupati (Sayut Pengambeyan Tumpeng 5).','Dewa p8+');
INSERT INTO kutipan(id,sumber_id,teks,halaman) VALUES (2127,9,'Prayascita (sarana pembersihan dan penyucian).','Dewa p8+');
INSERT INTO kutipan(id,sumber_id,teks,halaman) VALUES (2128,9,'Banten Durmanggala','Dewa p8+');
INSERT INTO kutipan(id,sumber_id,teks,halaman) VALUES (2129,9,'Biokala / Biyakala (pembersihan diri/kendaraan dari energi buruk).','Dewa p8+');
INSERT INTO kutipan(id,sumber_id,teks,halaman) VALUES (2130,9,'Banten Pasupati / Sesayut Pasupati.','Dewa p8+');
INSERT INTO kutipan(id,sumber_id,teks,halaman) VALUES (2131,9,'Gantungan + Sasat serta Segehan Barak.','Dewa p8+');
INSERT INTO kutipan(id,sumber_id,teks,halaman) VALUES (2132,9,'Kelengkapan pendukung: Canang sari, tirtha','Dewa p8+');
